{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "In healthy volunteers, pethidine had an absolute oral bioavailability of 0.61 versus IV, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "In humans, maraviroc 100 mg tablet had an absolute oral bioavailability of 23.1% (95% CI 19.2-27.8), above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "In humans, milnacipran had an absolute oral bioavailability of 85 ± 3%, well above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Direct absolute oral bioavailability measurements in healthy subjects for multiple evidence molecules are consistently above 20%, ranging from about 23% to over 90%. The only sub-20% numeric record is metabolite-related after prodrug administration and is endpoint-mismatched, so high bioavailability is better supported.",
  "evidence_gaps": [
    "Molecule 4 records report S-9780/perindoprilat availability after oral perindopril rather than direct absolute oral bioavailability of the parent drug, limiting their weight.",
    "One qualitative pethidine record (C25) reports 'Low' but is contradicted by multiple numeric absolute bioavailability measurements above 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

